-- ============================================================
-- Customer Analytics SQLite Database Backup Dump
-- Includes DROP TABLE IF EXISTS, CREATE TABLE, and INSERT queries
-- ============================================================
BEGIN TRANSACTION;

-- DROP TABLE IF EXISTS "detections";
CREATE TABLE detections (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    track_id        INTEGER,
    raw_track_id    INTEGER,
    camera_id       TEXT NOT NULL,
    mode            TEXT NOT NULL,
    timestamp       TEXT NOT NULL,
    bbox            TEXT NOT NULL,             -- JSON [x1,y1,x2,y2]
    confidence      REAL,
    crop_path       TEXT,
    upper_garment   TEXT,
    lower_garment   TEXT,
    gender          TEXT,
    gender_conf     REAL,
    upper_hist      BLOB,                      -- float32 HSV histogram, L2-normalized
    lower_hist      BLOB,                      -- float32 HSV histogram, L2-normalized
    extra           TEXT                       -- JSON for anything else
, last_seen TEXT, frame_count INTEGER DEFAULT 1);

-- DROP TABLE IF EXISTS "face_embeddings";
CREATE TABLE face_embeddings (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    track_id        INTEGER,
    camera_id       TEXT NOT NULL,
    detection_id    INTEGER REFERENCES detections(id) ON DELETE SET NULL,
    timestamp       TEXT NOT NULL,
    vector          BLOB NOT NULL,             -- float32[512], L2-normalized
    det_confidence  REAL,
    quality         REAL,                      -- composite score in [0,1]
    face_crop_path  TEXT
);

-- DROP TABLE IF EXISTS "garment_colors";
CREATE TABLE garment_colors (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    detection_id    INTEGER NOT NULL REFERENCES detections(id) ON DELETE CASCADE,
    slot            TEXT NOT NULL CHECK (slot IN ('upper','lower')),
    rank            INTEGER NOT NULL,          -- 0 = primary, 1 = secondary, ...
    color_name      TEXT NOT NULL,
    percentage      REAL NOT NULL,
    rgb             TEXT                       -- JSON [r,g,b]
);

-- DROP TABLE IF EXISTS "roi_walkins_video";
CREATE TABLE roi_walkins_video (
    id                  INTEGER PRIMARY KEY AUTOINCREMENT,
    camera_id           TEXT NOT NULL,
    track_id            INTEGER,
    stable_id           INTEGER NOT NULL,
    roi_name            TEXT DEFAULT 'Default ROI',
    entry_timestamp     TEXT NOT NULL,
    exit_timestamp      TEXT,
    reentry_count       INTEGER DEFAULT 0,
    dwell_seconds       REAL DEFAULT 0.0,
    best_crop_path      TEXT,
    best_face_crop_path TEXT,
    best_quality_score  REAL DEFAULT 0.0,
    status              TEXT NOT NULL CHECK (status IN ('INSIDE', 'EXITED'))
);

-- DROP TABLE IF EXISTS "walkin_sessions";
CREATE TABLE walkin_sessions (
    id                      INTEGER PRIMARY KEY AUTOINCREMENT,
    session_id              INTEGER UNIQUE,
    stable_id               INTEGER NOT NULL,
    camera_id               TEXT NOT NULL,
    entry_timestamp         REAL NOT NULL,
    last_seen_timestamp     REAL NOT NULL,
    exit_timestamp          REAL,
    dwell_seconds           REAL NOT NULL DEFAULT 0.0,
    status                  TEXT NOT NULL DEFAULT 'INSIDE',
    best_crop_path          TEXT,
    best_face_crop_path     TEXT,
    reentry_count           INTEGER DEFAULT 0
);

CREATE INDEX idx_det_ts ON detections(timestamp);
CREATE INDEX idx_det_cam ON detections(camera_id);
CREATE INDEX idx_det_track ON detections(track_id, camera_id);
CREATE INDEX idx_det_gender ON detections(gender);
CREATE INDEX idx_color_slot_name ON garment_colors(slot, color_name);
CREATE INDEX idx_color_det ON garment_colors(detection_id);
CREATE INDEX idx_face_track ON face_embeddings(track_id, camera_id);
CREATE INDEX idx_face_ts ON face_embeddings(timestamp);
CREATE INDEX idx_walkins_stable ON roi_walkins_video(stable_id, camera_id);
CREATE INDEX idx_walkins_status ON roi_walkins_video(status, camera_id);
CREATE INDEX idx_walkins_entry ON roi_walkins_video(entry_timestamp);
CREATE INDEX idx_walkin_track ON walkin_sessions(stable_id, camera_id);
CREATE INDEX idx_walkin_status ON walkin_sessions(status);
DELETE FROM "sqlite_sequence";

COMMIT;